<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/** Phase 7D screens inside the private CRM (prospect list, prospect page, acquisition dashboard). Helpers (crm_h, crm_form, crm_f_*, crm_tbl) come from crm_views.php. */
require_once __DIR__ . '/crm_acquisition.php';

function crm_acq_checks(string $name, array $opts, array $sel): string { $o = '<fieldset><legend>' . crm_h($name) . '</legend>'; foreach ($opts as $k => $l) $o .= '<label style="display:block;min-height:44px"><input type="checkbox" name="services[]" value="' . crm_h($k) . '"' . (in_array($k, $sel, true) ? ' checked' : '') . '> ' . crm_h($l) . '</label>'; return $o . '</fieldset>'; }
function crm_acq_profile_fields(array $p, array $users): string {
  $sel = array_values(array_filter(explode(',', (string)($p['services'] ?? '')))); $est = ($p['est_value_minor'] ?? null) === null ? '' : number_format($p['est_value_minor'] / 100, 2, '.', '');
  return crm_f_input('company', 'Company', (string)($p['company_name'] ?? '')) . crm_f_input('website', 'Website (https://…)', (string)($p['website'] ?? '')) . crm_f_input('country', 'Country (name or 2-letter code)', (string)($p['country'] ?? '')) . crm_f_input('region', 'Region', (string)($p['region'] ?? ''))
    . crm_f_select('industry', 'Industry', crm_acq_industries(), (string)($p['industry'] ?? ''), true) . crm_f_select('size_band', 'Company size', crm_acq_sizes(), (string)($p['size_band'] ?? ''), true) . crm_acq_checks('Relevant TrustNova services', crm_acq_services(), $sel)
    . crm_f_area('requirements', 'Business requirements (what the company needs, from public information or their own words)', (string)($p['requirements'] ?? '')) . crm_f_area('automation_notes', 'Potential automation opportunities (your assessment)', (string)($p['automation_notes'] ?? ''))
    . crm_f_select('budget_info', 'Budget information', crm_acq_budget_kinds(), (string)($p['budget_info'] ?? 'unknown')) . crm_f_select('urgency', 'Project urgency', crm_acq_urgency_kinds(), (string)($p['urgency'] ?? 'unknown')) . crm_f_input('urgency_note', 'Source of the urgency (required unless unknown)', (string)($p['urgency_note'] ?? ''))
    . crm_f_input('est_value', 'Estimated project value (internal ESTIMATE, not a quote or forecast)', $est) . crm_f_select('est_currency', 'Currency', array_combine(crm_currencies(), crm_currencies()), (string)($p['est_currency'] ?? 'EUR')) . crm_f_input('est_basis', 'How the estimate was made (required with a value)', (string)($p['est_basis'] ?? ''))
    . crm_f_area('notes', 'Research notes (company level; no e-mail addresses or phone numbers)', (string)($p['notes'] ?? '')) . crm_f_input('next_action', 'Next action', (string)($p['next_action'] ?? '')) . crm_f_input('next_action_at', 'Follow-up date (YYYY-MM-DD)', (string)($p['next_action_at'] ?? '')) . crm_f_select('owner_id', 'Prospect owner', $users, (string)($p['owner_id'] ?? ''), true);
}
function crm_acq_status_badge(string $st): string { $cls = in_array($st, ['do_not_contact', 'not_interested'], true) ? 'badge3 badge3--warn' : (in_array($st, ['responded', 'consultation_requested', 'converted_to_lead'], true) ? 'badge3 badge3--ok' : 'badge3'); return '<span class="' . $cls . '">' . crm_h(crm_acq_statuses()[$st] ?? $st) . '</span>'; }
function crm_acq_money(?int $minor, string $cur): string { return $minor === null ? '—' : crm_h(crm_money_format($minor, $cur)) . ' <span class="small">(estimate)</span>'; }
function crm_acq_values(array $v): string { if (!$v) return '—'; $o = []; foreach ($v as $c => $m) $o[] = crm_money_format((int)$m, (string)$c); return crm_h(implode(' / ', $o)) . ' <span class="small">(estimates)</span>'; }

function crm_acq_view_prospects(PDO $pdo, array $u, array $q, array $users): void {
  $canW = crm_can($u['role'], 'write'); $ready = crm_acq_ready($pdo); $f = ['status' => (string)($q['status'] ?? ''), 'country' => (string)($q['country'] ?? ''), 'industry' => (string)($q['industry'] ?? ''), 'service' => (string)($q['service'] ?? ''), 'q' => (string)($q['q'] ?? ''), 'due' => !empty($q['due'])];
  echo '<h2>Prospects (corporate customer research)</h2><p class="small">Company-level research only: no personal contact details, no scraping. Nothing is contacted from here. Values are internal estimates.</p>';
  if (!$ready) { echo '<div class="noteBox" role="status">The acquisition features need the Phase 7D database migration (database/phase7d_acquisition.sql). Until then this page shows the basic Phase 6 prospect records.</div>'; echo crm_tbl('Prospects', ['#', 'Company', 'Kind', 'Fit', 'Source'], array_map(fn($x) => [(int)$x['id'], crm_h($x['company_name']), crm_h(crm_lead_kinds()[$x['kind']] ?? $x['kind']), crm_h(crm_prospect_fit_statuses()[$x['fit_status']] ?? ''), crm_h($x['source_url'] ?: '—')], crm_prospects_list($pdo))); return; }
  echo '<form method="get" action="/crm.php" class="crmForm"><input type="hidden" name="v" value="prospects">' . crm_f_input('q', 'Search company', $f['q']) . crm_f_select('status', 'Status', crm_acq_statuses(), $f['status'], true) . crm_f_input('country', 'Country code', $f['country']) . crm_f_select('industry', 'Industry', crm_acq_industries(), $f['industry'], true) . crm_f_select('service', 'Service', crm_acq_services(), $f['service'], true) . '<label style="display:inline-flex;align-items:center;min-height:44px;gap:8px"><input type="checkbox" name="due" value="1"' . ($f['due'] ? ' checked' : '') . '> Overdue follow-ups only</label> <button class="btn sm">Filter</button> <a class="btn sm secondary" href="/crm.php?v=prospects&amp;export=csv">Export CSV</a></form>';
  $rows = crm_acq_list($pdo, $f);
  echo crm_tbl('Prospects', ['Company', 'Country', 'Industry', 'Services', 'Status', 'Score', 'Estimate', 'Next action'], array_map(fn($p) => ['<a href="/crm.php?v=prospect&amp;id=' . (int)$p['id'] . '">' . crm_h($p['company_name']) . '</a>' . ($p['suppressed'] ? ' <span class="badge3 badge3--warn">Suppressed</span>' : '') . '<br><span class="small">' . crm_h($p['website']) . '</span>', crm_h(crm_acq_country_label((string)$p['country'])), crm_h(crm_acq_industries()[$p['industry']] ?? '—'), crm_h(implode(', ', array_map(fn($k) => crm_acq_services()[$k] ?? $k, array_filter(explode(',', (string)$p['services'])))) ?: '—'), crm_acq_status_badge($p['status']), '<span class="badge3" title="Out of 100">' . (int)$p['score']['score'] . ' ' . crm_h(crm_acq_band_label($p['score']['band'])) . '</span>', crm_acq_money($p['est_value_minor'] === null ? null : (int)$p['est_value_minor'], (string)$p['est_currency']), crm_h($p['next_action'] ?: '—') . ($p['next_action_at'] ? '<br><span class="small">' . crm_h($p['next_action_at']) . (!in_array($p['status'], ['converted_to_lead', 'not_interested', 'do_not_contact'], true) && $p['next_action_at'] < gmdate('Y-m-d') ? ' · <strong>overdue</strong>' : '') . '</span>' : '')], $rows));
  if (!$canW) return;
  echo '<h3>Add a prospect</h3>' . crm_form('acq_create', [], crm_acq_profile_fields([], $users) . crm_f_input('source_url', 'Public source URL (company website, register, press release)') . crm_f_input('source_label', 'Source label'), 'Add prospect');
  echo '<h3>Import companies from CSV</h3><p class="small">Columns: ' . crm_h(implode(', ', crm_acq_csv_columns())) . '. Only the first column (company) is required. Rows are validated first; companies that already exist (same website domain or name) are skipped. Max ' . CRM_ACQ_MAX_IMPORT_ROWS . ' rows. Company-level data only.</p>'
    . '<form method="post" action="/crm.php" enctype="multipart/form-data" class="crmForm">' . crm_csrf_field() . '<input type="hidden" name="act" value="prospect_import"><input type="hidden" name="dry" value="1"><div class="field"><label for="csvfile">CSV file</label><input id="csvfile" type="file" name="csvfile" accept=".csv,text/csv"></div>' . crm_f_area('csv', 'or paste CSV text', '', 5) . '<button class="btn sm">Check the file (nothing is saved yet)</button></form>';
}

function crm_acq_import_result_html(array $res, string $csv): string {
  if (empty($res['ok'])) return '<div class="noteBox" role="alert">Import not possible: ' . crm_h(str_replace('_', ' ', (string)$res['error'])) . '.</div>';
  $o = '<h2>CSV ' . ($res['dry'] ? 'check' : 'import') . '</h2><p>' . ($res['dry'] ? 'Nothing was saved. ' : '') . '<strong>' . (int)$res['created'] . '</strong> ' . ($res['dry'] ? 'would be created' : 'created') . ', <strong>' . (int)$res['duplicates'] . '</strong> duplicates skipped, <strong>' . (int)$res['errors'] . '</strong> rows with errors.' . ($res['ignored_columns'] ? ' Ignored columns: ' . crm_h(implode(', ', $res['ignored_columns'])) . '.' : '') . '</p>';
  $o .= crm_tbl('Rows', ['Line', 'Company', 'Result', 'Detail'], array_map(fn($r) => [(int)$r['line'], crm_h($r['company']), crm_h(['would_create' => 'Would create', 'created' => 'Created', 'duplicate' => 'Duplicate (skipped)', 'error' => 'Error'][$r['result']] ?? $r['result']), crm_h(str_replace('_', ' ', $r['message']))], $res['rows']));
  if ($res['dry'] && $res['created'] > 0) $o .= '<form method="post" action="/crm.php" class="crmForm">' . crm_csrf_field() . '<input type="hidden" name="act" value="prospect_import"><input type="hidden" name="dry" value="0"><input type="hidden" name="csv" value="' . crm_h($csv) . '"><button class="btn">Import the ' . (int)$res['created'] . ' valid companies</button></form>';
  return $o . '<p><a href="/crm.php?v=prospects">Back to prospects</a></p>';
}

function crm_acq_view_prospect(PDO $pdo, array $u, int $id, array $q, array $users): void {
  $p = crm_acq_get($pdo, $id); if (!$p) { echo '<p>Prospect not found.</p>'; return; } $canW = crm_can($u['role'], 'write'); $ready = crm_acq_ready($pdo); $sc = $p['score'];
  echo '<h2>' . crm_h($p['company_name']) . ' ' . crm_acq_status_badge($p['status']) . ($p['suppressed'] ? ' <span class="badge3 badge3--warn">On the suppression list</span>' : '') . '</h2>';
  if (!$ready) { echo '<div class="noteBox" role="status">Needs the Phase 7D database migration for the acquisition profile.</div>'; return; }
  if ($p['suppressed'] || $p['status'] === 'do_not_contact') echo '<div class="noteBox" role="alert">Do not contact this company. Drafts and contact steps are blocked.</div>';
  echo '<div class="panel"><dl class="small"><dt>Website</dt><dd>' . crm_h($p['website'] ?: '—') . '</dd><dt>Country / region</dt><dd>' . crm_h(crm_acq_country_label((string)$p['country'])) . ($p['region'] ? ' · ' . crm_h($p['region']) : '') . '</dd><dt>Industry / size</dt><dd>' . crm_h(crm_acq_industries()[$p['industry']] ?? '—') . ' · ' . crm_h(crm_acq_sizes()[$p['size_band']] ?? '—') . '</dd><dt>Relevant services</dt><dd>' . crm_h(implode(', ', array_map(fn($k) => crm_acq_services()[$k] ?? $k, array_filter(explode(',', (string)$p['services'])))) ?: '—') . '</dd>'
    . '<dt>Estimated project value</dt><dd>' . crm_acq_money($p['est_value_minor'] === null ? null : (int)$p['est_value_minor'], (string)$p['est_currency']) . ($p['est_basis'] ? '<br>Basis: ' . crm_h($p['est_basis']) : '') . '</dd><dt>Budget / urgency</dt><dd>' . crm_h(crm_acq_budget_kinds()[$p['budget_info']] ?? '') . ' · ' . crm_h(crm_acq_urgency_kinds()[$p['urgency']] ?? '') . ($p['urgency_note'] ? ' (' . crm_h($p['urgency_note']) . ')' : '') . '</dd><dt>Owner</dt><dd>' . crm_h($p['owner_name'] ?: '—') . '</dd><dt>Next action</dt><dd>' . crm_h($p['next_action'] ?: '—') . ($p['next_action_at'] ? ' · ' . crm_h($p['next_action_at']) : '') . '</dd>'
    . '<dt>Requirements</dt><dd>' . nl2br(crm_h((string)$p['requirements'] ?: '—')) . '</dd><dt>Automation opportunities</dt><dd>' . nl2br(crm_h((string)$p['automation_notes'] ?: '—')) . '</dd><dt>Research notes</dt><dd>' . nl2br(crm_h($p['notes'] ?: '—')) . '</dd></dl></div>';
  echo '<h3>Score ' . (int)$sc['score'] . '/100: ' . crm_h(crm_acq_band_label($sc['band'])) . '</h3><p class="small">Built only from what has been recorded (' . (int)$sc['recorded'] . ' of ' . (int)$sc['of'] . ' inputs). Weights are planning assumptions, not measured win rates; nothing is guessed.</p>'
    . crm_tbl('Score explanation', ['Input', 'What was recorded', 'Points'], array_map(fn($r) => [crm_h($r['group']), crm_h($r['why']), (int)$r['pts'] . ' / ' . (int)$r['max']], $sc['reasons'])) . ($sc['missing'] ? '<p class="small">Still to research: ' . crm_h(implode(', ', $sc['missing'])) . '.</p>' : '');
  echo '<h3>Public information sources</h3>' . ($p['sources'] ? '<ul class="small">' . implode('', array_map(fn($s) => '<li><a href="' . crm_h($s['url']) . '" rel="noopener nofollow noreferrer" target="_blank">' . crm_h($s['label'] ?: $s['url']) . '</a> · checked ' . crm_h($s['checked'] ?? '') . '</li>', $p['sources'])) . '</ul>' : '<p class="small">No sources recorded yet.</p>');
  if ($canW) echo crm_form('acq_source', ['id' => $id], crm_f_input('url', 'Public source URL (https://…)') . crm_f_input('label', 'Label (e.g. company website, annual report)') . crm_f_input('checked', 'Date checked (YYYY-MM-DD)', gmdate('Y-m-d')), 'Add source');
  // workflow
  echo '<h3>Status and contact permission</h3><p>Contact permission basis: <strong>' . crm_h(crm_acq_contact_bases()[$p['contact_basis']] ?? $p['contact_basis']) . '</strong>' . ($p['contact_basis_note'] ? ' (' . crm_h($p['contact_basis_note']) . ')' : '') . '</p><p class="small">A company can only be marked as contacted when a permission basis is recorded and it is not suppressed. Manual sending does not bypass consent or marketing-law requirements; check the rules for the country and channel. This system records the basis, it does not decide what is lawful.</p>';
  if ($canW) {
    echo crm_form('acq_basis', ['id' => $id], crm_f_select('basis', 'Contact permission basis', crm_acq_contact_bases(), $p['contact_basis']) . crm_f_input('note', 'Note (where and when; required unless none; no personal contact data)', (string)$p['contact_basis_note']), 'Save permission basis');
    $moves = array_filter(crm_acq_statuses(), fn($k) => in_array($k, crm_acq_transitions()[$p['status']] ?? [], true), ARRAY_FILTER_USE_KEY); if ($moves) echo crm_form('acq_move', ['id' => $id], crm_f_select('to', 'Move to', $moves) . crm_f_input('note', 'Note (required for not interested and do not contact)'), 'Change status');
  }
  $h = $pdo->prepare('SELECT h.*, u.display_name FROM crm_prospect_status_history h LEFT JOIN crm_users u ON u.id = h.changed_by WHERE h.prospect_id = ? ORDER BY h.id DESC'); $h->execute([$id]);
  echo crm_tbl('Status history', ['When', 'From', 'To', 'Note', 'By'], array_map(fn($x) => [crm_h($x['changed_at']), crm_h(crm_acq_statuses()[$x['from_status']] ?? '—'), crm_h(crm_acq_statuses()[$x['to_status']] ?? $x['to_status']), crm_h($x['note'] ?: '—'), crm_h($x['display_name'] ?: 'system')], $h->fetchAll(PDO::FETCH_ASSOC)));
  if ($p['suppressed'] && crm_can($u['role'], 'approve')) echo crm_form('acq_unsuppress', ['id' => $id], crm_f_input('reason', 'Reason for lifting the suppression (owner only)'), 'Lift suppression');
  // conversion
  if ($p['lead_id'] !== null) echo '<h3>Converted</h3><p>CRM lead: ' . crm_link('lead', (int)$p['lead_id'], '#' . (int)$p['lead_id']) . '. A prospect converts only once.</p>';
  elseif ($canW && in_array($p['status'], ['responded', 'consultation_requested'], true) && !$p['suppressed']) echo '<h3>Convert to a CRM lead</h3><p class="small">Use only the contact details the company itself gave you in its reply or request. This creates one lead; it cannot be repeated.</p>' . crm_form('acq_convert', ['id' => $id], crm_f_input('name', 'Contact name') . crm_f_input('email', 'Business e-mail the company gave us', '', 'email') . crm_f_area('message', 'What they asked for or replied (summary)'), 'Convert to lead');
  // outreach
  echo '<h3>Outreach drafts</h3><div class="noteBox" role="status">Drafts are text for a person to review and personalise. This system sends nothing and never will; no contact data is collected for you.</div>';
  if (crm_can($u['role'], 'outreach') && !$p['suppressed'] && !in_array($p['status'], ['do_not_contact', 'not_interested'], true)) {
    $svc = (string)($q['svc'] ?? ''); $lang = in_array($q['lang'] ?? '', ['en', 'de'], true) ? $q['lang'] : 'en'; $tpl = $svc !== '' ? crm_acq_template($svc, $lang, $p) : null;
    echo '<form method="get" action="/crm.php" class="crmForm"><input type="hidden" name="v" value="prospect"><input type="hidden" name="id" value="' . $id . '">' . crm_f_select('svc', 'Service template', crm_acq_services(), $svc, true) . crm_f_select('lang', 'Language', ['en' => 'English', 'de' => 'Deutsch'], $lang) . '<button class="btn sm">Load template</button></form>';
    echo crm_form('acq_draft', ['id' => $id], crm_f_input('subject', 'Subject', (string)($tpl['subject'] ?? '')) . crm_f_area('body', 'Body. Complete every {{placeholder}} (name, a specific observation from public information, sender, legal notice) before review.', (string)($tpl['body'] ?? ''), 12), 'Save draft');
  }
  $ds = $pdo->prepare('SELECT * FROM crm_outreach_drafts WHERE prospect_id = ? ORDER BY id DESC'); $ds->execute([$id]);
  foreach ($ds->fetchAll(PDO::FETCH_ASSOC) as $d) { $un = crm_acq_unresolved($d['subject'] . ' ' . $d['body']); $text = $d['subject'] . "\n\n" . $d['body'];
    echo '<div class="panel"><strong>Draft #' . (int)$d['id'] . '</strong> · ' . crm_h($d['status']) . ($un ? ' · <span class="badge3 badge3--warn">Unfilled: ' . crm_h(implode(', ', $un)) . '</span>' : '') . ($p['contact_basis'] === 'none' ? ' · <span class="badge3 badge3--warn">No contact permission recorded: do not send</span>' : '')
      . '<textarea readonly rows="8" id="dr' . (int)$d['id'] . '" style="width:100%">' . crm_h($text) . '</textarea><button type="button" class="btn sm secondary" onclick="var t=document.getElementById(\'dr' . (int)$d['id'] . '\');t.select();navigator.clipboard&&navigator.clipboard.writeText(t.value)">Copy to clipboard</button>'
      . (crm_can($u['role'], 'outreach') ? crm_form('outreach_status', ['id' => $d['id'], 'back' => 'prospect&id=' . $id], crm_f_select('to', 'Status', ['draft' => 'Draft', 'reviewed' => 'Reviewed (placeholders filled)', 'archived' => 'Archived'], $d['status']), 'Set', 'inline') : '') . '</div>'; }
  if ($canW) echo '<h3>Edit the profile</h3>' . crm_form('acq_update', ['id' => $id], crm_acq_profile_fields($p, $users), 'Save profile');
  echo crm_notes_block($pdo, $u, 'prospect', $id);
}

function crm_acq_view_dashboard(PDO $pdo): void {
  $d = crm_acq_dashboard($pdo); echo '<h2>Customer acquisition</h2><p class="small">Every figure comes from recorded prospects, their status history and CRM leads. Estimates are internal and are never revenue.</p>';
  if (!$d['ready']) { echo '<div class="noteBox" role="status">Needs the Phase 7D database migration (database/phase7d_acquisition.sql). ' . (int)$d['total'] . ' basic prospect record(s) exist.</div>'; return; }
  $t = fn(string $l, $v, string $n = '') => '<li class="tile"><h3>' . crm_h($l) . '</h3>' . ($v === null ? '<div class="nv">Not enough data</div>' : '<div class="val">' . crm_h((string)$v) . '</div>') . ($n !== '' ? '<p>' . crm_h($n) . '</p>' : '') . '</li>';
  echo '<style>.acqGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;padding:0;list-style:none}.acqGrid .tile{border:1px solid var(--glass-line,#ddd);border-radius:12px;padding:12px;background:var(--surface,#fff)}.acqGrid .val{font-size:1.6rem;font-weight:700}.acqGrid h3{font-size:.85rem;margin:0 0 4px}.acqGrid p{margin:4px 0 0;font-size:.8rem}</style><ul class="acqGrid">'
    . $t('Total researched companies', $d['researched'], 'Beyond "Identified" (of ' . (int)$d['total'] . ' recorded).') . $t('Qualified prospects', $d['qualified'], 'Currently in "Qualified".') . $t('Awaiting action', $d['awaiting'], 'Statuses where the next step is ours.') . $t('Companies contacted', $d['contacted'], 'Ever reached "Contacted" (status history).')
    . $t('Responses received', $d['responded'], 'Ever reached "Responded".') . $t('Consultations requested', $d['consultations'], 'Ever reached "Consultation requested".') . $t('Converted leads', $d['converted'], 'Prospects converted to a CRM lead.') . $t('Prospect conversion rate', $d['rate'] === null ? null : $d['rate'] . '%', $d['rate'] === null ? 'No company has been contacted yet.' : 'Converted leads / companies contacted.') . $t('Overdue follow-ups', $d['overdue'], 'Follow-up date passed, still open.') . '</ul>';
  echo '<h3>Pipeline by status</h3>' . crm_tbl('By status', ['Status', 'Companies'], array_map(fn($k, $n) => [crm_h(crm_acq_statuses()[$k] ?? $k), (int)$n], array_keys($d['by_status']), array_values($d['by_status'])));
  $grp = fn(string $title, array $g, callable $label) => '<h3>' . crm_h($title) . '</h3>' . crm_tbl($title, ['Group', 'Open prospects', 'Estimated value'], array_map(fn($k, $v) => [crm_h($label($k)), (int)$v['n'], crm_acq_values($v['value'])], array_keys($g), array_values($g)));
  echo $grp('Opportunities by industry', $d['by_industry'], fn($k) => crm_acq_industries()[$k] ?? $k) . $grp('Opportunities by country', $d['by_country'], fn($k) => strlen($k) === 2 ? crm_acq_country_label($k) : $k) . $grp('Opportunities by service', $d['by_service'], fn($k) => crm_acq_services()[$k] ?? $k) . '<p class="small">Open prospects exclude converted, not interested and do not contact. A company with several services counts once under each; its value is shown only where a single service is recorded. Values are internal estimates in their own currency, never summed across currencies.</p>';
  echo '<h3>Overdue follow-ups</h3>' . crm_tbl('Overdue', ['Company', 'Status', 'Next action', 'Due'], array_map(fn($r) => ['<a href="/crm.php?v=prospect&amp;id=' . (int)$r['id'] . '">' . crm_h($r['company']) . '</a>', crm_acq_status_badge($r['status']), crm_h($r['action'] ?: '—'), crm_h($r['due'])], $d['overdue_list']));
}
